spec.setup_code:
var __inner = (function () {
var BLUE=[11,79,192],WARM=[180,85,47],TEAL=[19,131,116],GREY=[128,152,188];
var INK='#04204B',SEC='#3D5F91',GUIDE='#8098BC';
var spin=0,spinSlow=0;
var titles=['1  The market clears','2  The line is overloaded','3  Redispatch','4  Who pays'];
var descs=['Single bidding zone: the day-ahead result ignores internal lines. Wind 14 GW minus northern demand 6 GW leaves 8 GW to flow north to south.','The 8 GW schedule is more than the corridor can carry safely.','TSO redispatch: curtail 3 GW of northern wind, start 3 GW of southern gas. Total supply stays 19 GW.','Flow is back at 5 GW. The cost of the fix is passed on to consumers.'];
function mixc(a,b,t){return [a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t];}
function rgba(c,a){return 'rgba('+Math.round(c[0])+','+Math.round(c[1])+','+Math.round(c[2])+','+a+')';}
function ease(x){x=Math.max(0,Math.min(1,x));return x*x*(3-2*x);}
function wrap(ctx,text,maxW){var words=String(text||'').split(' '),lines=[],cur='';for(var i=0;i<words.length;i++){var t=cur?cur+' '+words[i]:words[i];if(ctx.measureText(t).width>maxW&&cur){lines.push(cur);cur=words[i];}else cur=t;}if(cur)lines.push(cur);return lines;}
function para(ctx,text,x,y,maxW,lh,align){ctx.textAlign=align||'left';var L=wrap(ctx,text,maxW);for(var i=0;i<L.length;i++)ctx.fillText(L[i],x,y+i*lh);return L.length;}
function turbine(ctx,x,base,h,ang,alpha){ctx.globalAlpha=alpha;ctx.strokeStyle=rgba(BLUE,1);ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,base);ctx.lineTo(x,base-h);ctx.stroke();for(var b=0;b<3;b++){var a=ang+b*2.0944;ctx.beginPath();ctx.moveTo(x,base-h);ctx.lineTo(x+Math.cos(a)*13,base-h+Math.sin(a)*13);ctx.stroke();}ctx.fillStyle=rgba(BLUE,1);ctx.beginPath();ctx.arc(x,base-h,2.5,0,6.283);ctx.fill();ctx.globalAlpha=1;}
function plant(ctx,x,base,k,on){var c=mixc(GREY,WARM,on);if(on>0.01){ctx.fillStyle=rgba(WARM,0.28*on*(0.8+0.2*Math.sin(k*6)));ctx.beginPath();ctx.arc(x,base-10,18,0,6.283);ctx.fill();}ctx.fillStyle=rgba(c,1);ctx.fillRect(x-9,base-20,18,20);ctx.fillRect(x+3,base-30,5,10);ctx.strokeStyle=INK;ctx.lineWidth=1;ctx.strokeRect(x-9,base-20,18,20);}
return {draw:function(ctx,width,height,time,dt){
time=+time||0;dt=+dt||0.016;if(dt<0||dt>0.2)dt=0.016;
width=+width||600;height=+height||400;
ctx.fillStyle='#ffffff';ctx.fillRect(0,0,width,height);
var w=width,h=height;
var T=((time%10)+10)%10,idx=Math.max(0,Math.min(3,Math.floor(T/2.5))),lt=(T-idx*2.5)/2.5;
var k=idx<2?0:(idx==2?ease(lt/0.45):1);
var flow=8-3*k,wind=14-3*k,gas=5+3*k;
var cy=h*0.36;
var base=idx==0?BLUE:WARM;
var col=mixc(base,TEAL,k);
spin+=dt*3;spinSlow+=dt*3*(1-0.7*k);
for(var s=0;s<4;s++){ctx.fillStyle=s<=idx?rgba(BLUE,1):'#dde5f2';ctx.fillRect(16+s*(w-32)/4,8,(w-32)/4-4,4);}
ctx.font='bold 13px sans-serif';ctx.fillStyle=INK;ctx.textAlign='left';ctx.fillText('Phase '+titles[idx],16,32);
ctx.font='12px sans-serif';ctx.fillStyle=SEC;para(ctx,descs[idx],16,50,w-32,15,'left');
var bw=w*0.27,nx=w*0.03,sx=w*0.70;
ctx.lineWidth=1;ctx.strokeStyle=GUIDE;ctx.strokeRect(nx,cy-70,bw,152);ctx.strokeRect(sx,cy-70,bw,152);
ctx.font='bold 12px sans-serif';ctx.fillStyle=INK;ctx.textAlign='left';ctx.fillText('NORTH (coast)',nx+8,cy-54);ctx.fillText('SOUTH (industry)',sx+8,cy-54);
ctx.font='12px sans-serif';ctx.fillStyle=rgba(BLUE,1);ctx.fillText('wind '+Math.round(wind)+' GW',nx+8,cy-38);
ctx.fillStyle=rgba(WARM,1);ctx.fillText('gas '+Math.round(gas)+' GW',sx+8,cy-38);
ctx.fillStyle=INK;ctx.fillText('demand 6 GW',nx+8,cy+40);ctx.fillText('demand 13 GW',sx+8,cy+40);
for(var i=0;i<4;i++){var tx=nx+bw*(0.14+i*0.24);var dim=i>=2;turbine(ctx,tx,cy+22,28,(dim?spinSlow:spin)+i,dim?1-0.65*k:1);}
for(var j=0;j<3;j++){var px=sx+bw*(0.2+j*0.3);plant(ctx,px,cy+24,time,j<2?1:k);}
if(k>0.01){ctx.globalAlpha=k;ctx.font='12px sans-serif';ctx.fillStyle=rgba(BLUE,1);para(ctx,'curtailed, compensated: EUR',nx+8,cy+56,bw-14,14,'left');ctx.fillStyle=rgba(WARM,1);para(ctx,'ramped up, paid their costs',sx+8,cy+56,bw-14,14,'left');ctx.globalAlpha=1;}
var x1=w*0.31,x2=w*0.69,cx=(x1+x2)/2;
var pulse=(idx==1)?0.5+0.5*Math.sin(time*6):0;
ctx.fillStyle=rgba(col,0.12+0.1*pulse);ctx.fillRect(x1,cy-10,x2-x1,20);
ctx.strokeStyle=rgba(col,1);ctx.lineWidth=2+pulse*1.5;ctx.strokeRect(x1,cy-10,x2-x1,20);
ctx.fillStyle=rgba(col,1);ctx.beginPath();ctx.moveTo(x2,cy-14);ctx.lineTo(x2+10,cy);ctx.lineTo(x2,cy+14);ctx.fill();
var offs=[0,-4,4,-8,8,-12,12,-16];
for(var l=0;l<8;l++){var al=Math.max(0,Math.min(1,flow-l));if(al<=0.01)continue;var pc=l<5?col:WARM;ctx.fillStyle=rgba(pc,al);for(var m=0;m<6;m++){var u=(m/6+time*0.25+l*0.13)%1;ctx.beginPath();ctx.arc(x1+4+u*(x2-x1-8),cy+offs[l],2,0,6.283);ctx.fill();}}
ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillStyle=SEC;ctx.fillText('corridor capacity 5 GW',cx,cy-30);
var lab,lc;if(idx==0){lab='scheduled flow: 8 GW north to south';lc=BLUE;}else if(idx==1){lab='8 GW scheduled > 5 GW thermal limit (n-1 secure)';lc=WARM;}else if(idx==2){lab='flow '+flow.toFixed(1)+' GW, limit 5 GW';lc=col;}else{lab='flow 5 GW within the 5 GW limit: OK';lc=TEAL;}
ctx.font='bold 12px sans-serif';ctx.fillStyle=rgba(lc,1);para(ctx,lab,cx,cy+38,(x2-x1)+20,15,'center');
ctx.font='12px sans-serif';ctx.fillStyle=INK;ctx.textAlign='left';
var yb=cy+108;
ctx.fillText('Supply: wind '+Math.round(wind)+' + gas '+Math.round(gas)+' = '+Math.round(wind+gas)+' GW     Demand: 6 + 13 = 19 GW     Flow N to S: '+flow.toFixed(1)+' GW',16,yb);
if(idx==3){var e=ease(lt/0.5);ctx.font='bold 13px sans-serif';ctx.fillStyle=rgba(WARM,1);ctx.textAlign='left';ctx.fillText('Congestion management 2025: EUR '+(3.1*e).toFixed(1)+' billion',16,yb+24);
ctx.font='12px sans-serif';ctx.fillStyle=SEC;para(ctx,'In 2025, congestion management cost about EUR 3.1 billion (BNetzA), paid via network charges; HVDC lines SuedLink (2028) and SuedOstLink (2027) are meant to widen the corridor.',16,yb+44,w-32,15,'left');}
}};
})();
return { draw: function (ctx, w, h, t, dt) { ctx.save(); ctx.translate(0, 70); __inner.draw(ctx, w, h, t, dt); ctx.restore(); } };
